"""Deterministic synthetic demo data for D6 DISTRIBOX.

    ############################################################
    #  THIS IS SYNTHETIC DEMO DATA - NOT REAL HOTEL DATA.      #
    #  Generated by scripts/generate_demo_data.py using a fixed #
    #  RNG seed so every run is byte-for-byte reproducible.      #
    ############################################################

Design constraints
------------------
* Standard library only. No numpy, no pandas - the generator must run
  anywhere the backend runs, including a bare CI container.
* Fixed ``random.Random(seed)``. Reproducibility is not a nicety here:
  the demo narrative, the recorded screenshots and the unit tests all
  quote specific figures, and they must not drift between runs.
* Realistic *economics*, not realistic-looking noise. Commission rates
  are drawn per booking around a channel mean so that channel-level
  aggregates land near the configured rate but are not identical, which
  is what real channel statements look like.

The hotel is a 100-room Himalayan hill resort: strong seasonality
(peak May-June and September-October), a weekend premium, and a leisure
skew that produces long average stays.
"""

from __future__ import annotations

import random
from dataclasses import dataclass, field
from datetime import date, timedelta
from decimal import Decimal
from typing import Dict, List, Optional, Tuple

# ---------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------

