@dataclass
class GeneratedBooking:
    booking_id: str
    guest_external_id: str
    channel_code: str
    room_type_code: str
    booking_date: date
    check_in_date: date
    check_out_date: date
    room_nights: int
    gross_room_revenue: Decimal
    discount_amount: Decimal
    commission_amount: Decimal
    payment_fee: Decimal
    other_channel_cost: Decimal
    cancellation_status: str
    stay_status: str
    repeat_guest: bool
    guest_country: str
    booking_lead_days: int


@dataclass
class GeneratedGuest:
    external_id: str
    first_name: str
    last_name: str
    country: str


@dataclass
class DemoDataset:
    hotel: Dict
    room_types: List[Dict]
    channels: List[Dict]
    channel_costs: List[Dict]
    guests: List[GeneratedGuest]
    bookings: List[GeneratedBooking]
    period_start: date
    period_end: date

    def summary(self) -> Dict[str, object]:
        return {
            "bookings": len(self.bookings),
            "guests": len(self.guests),
            "channels": len(self.channels),
            "room_types": len(self.room_types),
            "period_start": self.period_start.isoformat(),
            "period_end": self.period_end.isoformat(),
            "cancelled": sum(
                1 for b in self.bookings if b.cancellation_status == "CANCELLED"
            ),
            "repeat_bookings": sum(1 for b in self.bookings if b.repeat_guest),
            "data_source": "demo_synthetic",
        }


# ---------------------------------------------------------------------
# Seasonality
# ---------------------------------------------------------------------

def _seasonal_occupancy(d: date) -> float:
    """Occupancy multiplier for a Himalayan resort.

    Peak: May-June (summer holidays) and September-October (post-monsoon
    clear views). Low: July-August (monsoon) and December-January (cold).
    Weekend uplift applies on top.
    """
    base_by_month = {
        1: 0.42, 2: 0.45, 3: 0.58, 4: 0.72, 5: 0.92, 6: 0.88,
        7: 0.48, 8: 0.52, 9: 0.86, 10: 0.90, 11: 0.63, 12: 0.50,
    }
    occ = base_by_month[d.month]
    if d.weekday() in (4, 5):  # Friday, Saturday
        occ *= 1.18
    elif d.weekday() == 6:  # Sunday
        occ *= 0.92
    return min(occ, 0.97)


def _seasonal_rate_multiplier(d: date) -> Decimal:
    """ADR multiplier aligned with the occupancy curve."""
    base_by_month = {
        1: 0.80, 2: 0.82, 3: 0.92, 4: 1.05, 5: 1.28, 6: 1.22,
        7: 0.85, 8: 0.90, 9: 1.24, 10: 1.30, 11: 0.96, 12: 0.86,
    }
    mult = Decimal(str(base_by_month[d.month]))
    if d.weekday() in (4, 5):
        mult *= Decimal("1.14")
    return mult.quantize(Decimal("0.001"))


def _pick(rng: random.Random, options: List[Tuple[str, float]]) -> str:
    """Weighted pick without numpy."""
    total = sum(w for _, w in options)
    roll = rng.random() * total
    cumulative = 0.0
    for value, weight in options:
        cumulative += weight
        if roll <= cumulative:
            return value
    return options[-1][0]


def _round2(value: Decimal) -> Decimal:
    return value.quantize(Decimal("0.01"))


def _jittered_rate(base: Decimal, sd: float, rng: random.Random) -> Decimal:
    """Draw a booking-level rate around a channel's configured mean.

    A channel configured at exactly zero stays at exactly zero. This
    matters: applying gaussian noise to a 0% commission would quietly
    start charging commission on *direct* bookings, which would corrupt
    the very comparison the demo exists to demonstrate (direct keeps
    everything, OTAs do not). Zero is a structural fact about a channel,
    not a mean to be jittered around.

    For a non-zero base the draw keeps genuine variance and is clamped
    into the valid [0, 1] range so no booking is ever generated with an
    impossible rate.
    """
    if base <= 0:
        return Decimal("0.00")
    rate = base + Decimal(str(rng.gauss(0, sd)))
    if rate < 0:
        return Decimal("0.00")
    if rate > 1:
        return Decimal("1.00")
    return _round2(rate)


def generate(
    n_bookings: int = 5000,
    n_guests: int = 1000,
    n_rooms: int = 100,
    period_end: Optional[date] = None,
    seed: int = RNG_SEED,
) -> DemoDataset:
    """Generate the full demo dataset deterministically."""
    rng = random.Random(seed)

    # Bookings are placed over the 12 months *ending* at period_end, and
    # stays must complete within the window, so the booking window is
    # pulled back by a typical lead time.
    period_end = period_end or date(2026, 8, 31)
    period_start = date(period_end.year - 1, period_end.month + 1, 1)

    # ---- room types ----
    room_types = [
        {"code": c, "name": n, "base_rate": Decimal(str(r)), "occupancy_weight": w}
        for c, n, r, w in ROOM_TYPES
    ]

    # ---- channels + cost config ----
    channels: List[Dict] = []
    channel_costs: List[Dict] = []
    for idx, (code, name, ctype, is_direct, mix, comm, comm_sd, pay, other, disc) in enumerate(
        CHANNELS
    ):
        channels.append(
            {
                "code": code,
                "name": name,
                "channel_type": ctype,
                "is_direct": is_direct,
                "sort_order": idx,
                "mix_weight": mix,
            }
        )
        for rt in room_types:
            # Per-room-type cost curves. OTAs charge more on luxury
            # inventory; corporate discounts deepen on suites.
            #
            # The luxury premium is applied *only* where there is a
            # commission to bias. Applying it to a channel whose base rate
            # is 0% would invent commission on direct and walk-in bookings
            # on suites - which would make direct look worse than it is and
            # corrupt the headline comparison.
            luxury = rt["code"] in {"SUI", "VLG"}
            base_comm = Decimal(str(comm))
            type_bias = Decimal("0.012") if (luxury and base_comm > 0) else Decimal("0")
            channel_costs.append(
                {
                    "channel_code": code,
                    "room_type_code": rt["code"],
                    "commission_rate": _round2(base_comm + type_bias),
                    "payment_fee_rate": _round2(Decimal(str(pay))),
                    "discount_rate": _round2(Decimal(str(disc))),
                    "other_cost_rate": _round2(Decimal(str(other))),
                    "expected_direct_conversion_rate": _round2(
                        Decimal(str(CHANNEL_ASSUMPTIONS[code]))
                    ),
                    # Share of a would-be-incremental booking that would
                    # land on another channel rather than being lost.
                    "incremental_rate": _round2(
                        Decimal("0.55") if ctype in {"OTA", "TRAVEL_AGENT"} else Decimal("0.40")
                    ),
                }
            )

    # ---- guests ----
    guests: List[GeneratedGuest] = []
    for i in range(1, n_guests + 1):
        guests.append(
            GeneratedGuest(
                external_id=f"GST{i:05d}",
                first_name=rng.choice(FIRST_NAMES),
                last_name=rng.choice(LAST_NAMES),
                country=_pick(rng, COUNTRIES),
            )
        )

    # Guest loyalty tiers. A minority of guests account for a
    # disproportionate share of stays, which is what creates genuine
    # direct-conversion opportunity in the analytics.
    loyalty_tier = [rng.random() for _ in guests]

    # ---- bookings ----
    bookings: List[GeneratedBooking] = []
    window_days = (period_end - period_start).days

    for n in range(1, n_bookings + 1):
        # Stay date distribution, sampled to match the occupancy curve.
        while True:
            candidate = period_start + timedelta(days=rng.randrange(window_days))
            if rng.random() < _seasonal_occupancy(candidate):
                break
        check_in = candidate

        # Length of stay: hill destinations skew long.
        nights = rng.choices(
            [1, 2, 3, 4, 5, 6, 7, 10, 14],
            weights=[26, 22, 16, 12, 9, 6, 4, 3, 2],
            k=1,
        )[0]
        check_out = check_in + timedelta(days=nights)

        # A loyal guest books further ahead and stays longer.
        tier = loyalty_tier[rng.randrange(n_guests)]
        if tier > 0.92:
            nights = max(nights, rng.choice([4, 5, 7, 10]))
            check_out = check_in + timedelta(days=nights)

        guest = guests[rng.randrange(n_guests)]
        repeat = tier > 0.55 and rng.random() < 0.62

        # Channel selection. Repeat guests skew direct, which is the
        # behavioural signal the conversion model will later learn.
        weights = []
        for ch in channels:
            w = ch["mix_weight"]
            if repeat:
                if ch["is_direct"]:
                    w *= 2.35
                elif ch["channel_type"] in {"OTA", "TRAVEL_AGENT"}:
                    w *= 0.62
            if tier > 0.92 and ch["is_direct"]:
                w *= 1.45
            weights.append((ch["code"], w))
        channel_code = _pick(rng, weights)
        channel = next(c for c in channels if c["code"] == channel_code)

        # Room type: loyal/long-stay guests skew premium.
        rt_weights = [
            (rt["code"], rt["occupancy_weight"] * (1.6 if (tier > 0.92 and rt["code"] in {"SUI", "VLG"}) else 1.0))
            for rt in room_types
        ]
        room_type_code = _pick(rng, rt_weights)
        room_type = next(r for r in room_types if r["code"] == room_type_code)

        # Lead time: OTAs get found later, corporate books early.
        base_lead = {"DIRECT": 34, "OTA_ALPHA": 19, "OTA_BETA": 15,
                     "TRAVEL_AGENT": 41, "CORPORATE": 27, "WALK_IN": 0}[channel_code]
        if channel_code == "WALK_IN":
            lead = 0
        else:
            lead = max(0, int(rng.gauss(base_lead, base_lead * 0.45)))
        booking_date = check_in - timedelta(days=lead)

        # ---- money ----
        nightly = _round2(
            Decimal(str(room_type["base_rate"])) * _seasonal_rate_multiplier(check_in)
        )
        gross = _round2(nightly * Decimal(nights))

        cost_cfg = next(
            c for c in channel_costs
            if c["channel_code"] == channel_code and c["room_type_code"] == room_type_code
        )

        # Discount is drawn around the channel mean with real variance.
        disc_rate = _jittered_rate(cost_cfg["discount_rate"], 0.018, rng)
        discount = _round2(gross * disc_rate)

        # Commission is charged on the *pre-discount* gross, which is how
        # OTA contracts actually work and is why net revenue hurts so much.
        # Direct and walk-in channels have a 0% base rate and therefore
        # stay at exactly 0%.
        comm_rate = _jittered_rate(cost_cfg["commission_rate"], 0.008, rng)
        commission = _round2(gross * comm_rate)

        # Payment fee: a small fixed component plus a percentage, as real
        # gateways charge.
        payment_fee = _round2(
            gross * Decimal(str(cost_cfg["payment_fee_rate"])) + Decimal("18")
        )

        other = _round2(gross * Decimal(str(cost_cfg["other_cost_rate"])))

        # Cancellations: concentrated on high-advance, high-fare bookings
        # and on the highest-commission channel (which has the strongest
        # incentive to free inventory for resale).
        cancel_p = 0.055
        if lead > 45:
            cancel_p += 0.035
        if channel_code in {"OTA_ALPHA", "OTA_BETA"}:
            cancel_p += 0.022
        cancelled = rng.random() < cancel_p

        bookings.append(
            GeneratedBooking(
                booking_id=f"BK{n:06d}",
                guest_external_id=guest.external_id,
                channel_code=channel_code,
                room_type_code=room_type_code,
                booking_date=booking_date,
                check_in_date=check_in,
                check_out_date=check_out,
                room_nights=0 if cancelled else nights,
                gross_room_revenue=gross,
                discount_amount=discount if not cancelled else _round2(gross),
                commission_amount=commission if not cancelled else Decimal("0.00"),
                payment_fee=payment_fee if not cancelled else Decimal("0.00"),
                other_channel_cost=other if not cancelled else Decimal("0.00"),
                cancellation_status="CANCELLED" if cancelled else "NOT_CANCELLED",
                stay_status="CANCELLED" if cancelled else "CHECKED_OUT",
                repeat_guest=repeat,
                guest_country=guest.country,
                booking_lead_days=lead,
            )
        )

    bookings.sort(key=lambda b: (b.booking_date, b.booking_id))

    return DemoDataset(
        hotel={**HOTEL, "total_rooms": n_rooms},
        room_types=room_types,
        channels=channels,
        channel_costs=channel_costs,
        guests=guests,
        bookings=bookings,
        period_start=period_start,
        period_end=period_end,
    )


if __name__ == "__main__":
    import json

    data = generate()
    print(json.dumps(data.summary(), indent=2))